<script lang="ts">type D=Record<string,any>;let {rows,cols,labels,csrf='',action=null,actionText=''}:{rows:D[],cols:string[],labels:string[],csrf?:string,action?:((r:D)=>string)|null,actionText?:string}=$props();const ask=(e:SubmitEvent)=>{if(!confirm(`${actionText} wirklich ausführen?`))e.preventDefault()};</script><div class="table-container"><table class="table"><thead><tr>{#each labels as l}<th>{l}</th>{/each}<th></th></tr></thead><tbody>{#each rows as r}<tr>{#each cols as c}<td>{r[c]??'–'}</td>{/each}<td>{#if action}<form method="post" action={action(r)} onsubmit={ask}><input type="hidden" name="csrf_token" value={csrf}><button class="button is-small is-danger">{actionText}</button></form>{/if}</td></tr>{:else}<tr><td colspan={labels.length+1}>Keine Einträge.</td></tr>{/each}</tbody></table></div>
